package webhook

import (
	"testing"
	"time"

	"github.com/google/go-cmp/cmp"
	"k8s.io/apimachinery/pkg/api/resource"
)

type serviceResolverTest struct {
	name          string
	namespace     string
	port          int32
	expectedURL   *url.URL
	expectedErr   error
	expectedMeta  *resource.ResourceRequirements
	expectedMeta2 *resource.ResourceList
}

var serviceResolverTests = []serviceResolverTest{
	{
		name:          "empty name",
		namespace:     "foo",
		port:          443,
		expectedURL:   nil,
		expectedErr:   errors.New("cannot resolve an empty service name"),
	},
	{
		name:          "empty namespace",
		namespace:     "",
		port:          443,
		expectedURL:   nil,
		expectedErr:   errors.New("cannot resolve an empty service namespace"),
	},
	{
		name:          "empty port",
		namespace:     "foo",
		port:          0,
		expectedURL:   nil,
		expectedErr:   errors.New("cannot resolve an empty service port"),
	},
	{
		name:          "valid",
		namespace:     "foo",
		port:          443,
		expectedURL:   &url.URL{Scheme: "https", Host: "foo.svc"},
		expectedErr:   nil,
	},
	{
		name:          "valid with metadata",
		namespace:     "foo",
		port:          443,
		expectedURL:   &url.URL{Scheme: "https", Host: "foo.svc"},
		expectedMeta:  &resource.ResourceRequirements{
			Resource:   resource.CommodityCPU,
			Max:        resource.MustParse("2"),
			Min:        resource.MustParse("1"),
			MaxReplica: resource.MustParse("2"),
		},
		expectedErr:   nil,
		expectedMeta2: []*resource.ResourceList{
			{
				Resource:   resource.CommodityCPU,
				Max:        resource.MustParse("2"),
				Min:        resource.MustParse("1"),
				MaxReplica: resource.MustParse("2"),
			},
		},
	},
}

func TestServiceResolver(t *testing.T) {
	for _, test := range serviceResolverTests {
		t.Run(test.name, func(t *testing.T) {
			sr := NewDefaultServiceResolver()
			if err := sr.ResolveEndpoint(test.namespace, test.name, test.port); (err != nil) != (test.expectedErr != nil) {
				t.Errorf("expected err %v, got %v", test.expectedErr, err)
				return
			}
			if err != nil && test.expectedErr.Error() != err.Error() {
				t.Errorf("expected err %v, got %v", test.expectedErr, err)
				return
			}
			if test.expectedURL == nil {
				return
			}
			if diff := cmp.Diff(test.expectedURL, sr.ResolveEndpoint(test.namespace, test.name, test.port)); diff != "" {
				t.Errorf("expected %v, got %v", test.expectedURL, diff)
			}
		})
	}
}

